const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let channel=0,paused=reduced,wavingUntil=0;
const canvas=document.querySelector('#world');
const names=['Tomorrow Works','Cosmic Kitchen','Little Planet'];
const types=["THE BUILDERS’ CHANNEL","EXPERIMENTAL DINING, EARTH OPTIONAL","SMALL CREATURES. BIG POSSIBILITIES."];
function draw(){window.dispatchEvent(new Event('tv-redraw'))}
function tune(n){channel=n;document.querySelector('#world-name').textContent=names[n];document.querySelector('#world-type').textContent=types[n];document.querySelector('#channel-number').textContent='CH 00'+(n+1);canvas.setAttribute('aria-label','Animated concept preview of '+names[n]);document.querySelectorAll('[data-channel]').forEach((b,i)=>{b.classList.toggle('active',i===n);b.setAttribute('aria-pressed',i===n)});document.querySelector('#dial').style.transform=`rotate(${n*120}deg)`;const screen=document.querySelector('.screen');screen.classList.remove('tuning');void screen.offsetWidth;screen.classList.add('tuning');draw()}
document.querySelectorAll('[data-channel]').forEach(b=>b.addEventListener('click',()=>tune(+b.dataset.channel)));document.querySelector('#dial').addEventListener('click',()=>tune((channel+1)%3));document.querySelectorAll('[data-preview]').forEach(b=>b.addEventListener('click',()=>{tune(+b.dataset.preview);document.querySelector('.broadcast').scrollIntoView({behavior:reduced?'instant':'smooth',block:'center'})}));
let reactionTimer;document.querySelector('#wave').addEventListener('click',()=>{wavingUntil=performance.now()+4500;const r=document.querySelector('#reaction');r.textContent=['“Hey, Earthling. We saved you a spot!”','“Hello! Care to taste the future?”','“A new friend! Welcome to our little world.”'][channel];r.classList.add('show');draw();clearTimeout(reactionTimer);reactionTimer=setTimeout(()=>r.classList.remove('show'),4500)});
const pause=document.querySelector('#pause');function syncPause(){pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'Play animation':'Pause animation');document.body.classList.toggle('paused',paused)}syncPause();pause.addEventListener('click',()=>{paused=!paused;syncPause()});
const dialog=document.querySelector('#app-dialog');document.querySelectorAll('[data-app]').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());document.querySelector('#back-demo').addEventListener('click',()=>{dialog.close();document.querySelector('#broadcast').scrollIntoView({behavior:reduced?'instant':'smooth'})});dialog.addEventListener('click',e=>{if(e.target===dialog){let r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});tune(0);

// The explanation is a hands-on sequence, independent of the channel previews.
const experience=document.querySelector('.transmission');
const experienceTabs=[...document.querySelectorAll('.experience-tabs [role="tab"]')];
const scenes=[
  {kicker:'YOUR WORLD IS OUT THERE',title:'Find your<br>frequency.',description:'Every channel is its own agentic environment, with a different cast, purpose, and way of life. Move the tuner to turn a distant signal into a connection.',message:'Move the tuner. Bring a new world into focus.'},
  {kicker:'INTELLIGENCE, IN MOTION',title:'Watch intelligence<br>happen.',description:'Meet the agents inside. See them plan, explore, and collaborate. Tap each agent to discover what happens between an idea and its next move.',message:'Tap a mind. Follow the thought.'},
  {kicker:'THE SIGNAL GOES BOTH WAYS',title:'Become part<br>of the picture.',description:'This television goes both ways. Send an idea into the world and watch the agents respond. You’re part of what happens next.',message:'Your idea can start something.'}
];
const agentNotes=[['01 / PLANNING','An intention becomes a plan. Watch an agent break a possibility into its next steps.','First, let’s figure out the next step.'],['02 / EXPLORING','Agents explore possibilities, try different approaches, and discover what their environment allows.','What if we tried something different?'],['03 / COLLABORATING','Individual actions become a shared effort. Agents exchange ideas and work toward something together.','Let’s connect the dots. Together.']];
let experienceMode=0,signalTimer;
const message=document.querySelector('#scene-message');
function setExperience(mode,focus=false){
  clearTimeout(signalTimer);experience.classList.remove('signal-sent');document.querySelector('#send-signal').disabled=false;document.querySelector('#send-signal').innerHTML='Send a spark of an idea <span>✳</span>';document.querySelector('#signal-hint').textContent='YOUR INPUT. THEIR NEXT MOVE.';experienceMode=mode;experience.dataset.mode=mode;
  experienceTabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===mode));tab.tabIndex=i===mode?0:-1});if(focus)experienceTabs[mode].focus();
  document.querySelector('#experience-panel').setAttribute('aria-labelledby',experienceTabs[mode].id);
  const data=scenes[mode];document.querySelector('#experience-kicker').textContent=data.kicker;document.querySelector('#experience-title').innerHTML=data.title;document.querySelector('#experience-description').textContent=data.description;message.textContent=data.message;
  ['tune','watch','join'].forEach((name,i)=>document.querySelector('#'+name+'-tools').hidden=i!==mode);
  document.querySelectorAll('[data-agent]').forEach(b=>{b.tabIndex=mode===1?0:-1;b.hidden=mode!==1});
  const next=document.querySelector('#next-experience');next.innerHTML=mode===0?'Meet the minds <span>02 →</span>':mode===1?'Make a move <span>03 →</span>':'Find your frequency again <span>01 ↺</span>';
  document.querySelector('#scene-frequency').textContent=['SIGNAL / SEARCHING','SIGNAL / OBSERVING','SIGNAL / TWO-WAY CONNECTION'][mode];
  const copy=document.querySelector('#copy-swap');copy.classList.remove('copy-enter');void copy.offsetWidth;copy.classList.add('copy-enter');if(mode===0)updateFrequency();
}
experienceTabs.forEach((tab,i)=>{tab.addEventListener('click',()=>setExperience(i));tab.addEventListener('keydown',e=>{let target;if(e.key==='ArrowRight')target=(i+1)%3;if(e.key==='ArrowLeft')target=(i+2)%3;if(e.key==='Home')target=0;if(e.key==='End')target=2;if(target!==undefined){e.preventDefault();setExperience(target,true)}})});
document.querySelector('#next-experience').addEventListener('click',()=>setExperience((experienceMode+1)%3));
function updateFrequency(){const value=Number(document.querySelector('#frequency').value);experience.style.setProperty('--signal',value/100);document.querySelector('#frequency-output').textContent=value+'%';const state=value<35?'SEARCHING':value<80?'DISCOVERING':'CONNECTED';document.querySelector('#frequency').setAttribute('aria-valuetext',value+' percent, '+state.toLowerCase());document.querySelector('#scene-frequency').textContent='SIGNAL / '+state;message.textContent=value<35?'Move the tuner. Bring a new world into focus.':value<80?'A little closer. There’s life on the other side.':'You found a connection. Now meet the minds.'}
document.querySelector('#frequency').addEventListener('input',updateFrequency);
document.querySelectorAll('[data-agent]').forEach(button=>button.addEventListener('click',()=>{const id=Number(button.dataset.agent),note=agentNotes[id];document.querySelectorAll('[data-agent]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('#agent-role').textContent=note[0];document.querySelector('#agent-detail').textContent=note[1];message.textContent=note[2]}));
document.querySelector('#send-signal').addEventListener('click',()=>{const button=document.querySelector('#send-signal');button.disabled=true;experience.classList.add('signal-sent');message.textContent='Your spark reached the agents. A new idea is taking shape.';document.querySelector('#signal-hint').textContent='SIGNAL RECEIVED → EXPLORING TOGETHER';signalTimer=setTimeout(()=>{button.disabled=false;button.innerHTML='Send another spark <span>✳</span>';message.textContent='A shared idea. And you started it.';experience.classList.remove('signal-sent');},3000)});
const scenePause=document.querySelector('#scene-pause');let scenePaused=reduced;function updateScenePause(){experience.classList.toggle('scene-paused',scenePaused);scenePause.textContent=scenePaused?'▶':'Ⅱ';scenePause.setAttribute('aria-label',scenePaused?'Play experience animation':'Pause experience animation')}scenePause.addEventListener('click',()=>{scenePaused=!scenePaused;updateScenePause()});updateScenePause();setExperience(0);
